import React, { useState, useRef } from "react";
import { 
  X, User, Truck, AlertCircle, BookOpen, 
  CheckCircle, Activity, MapPin
} from "lucide-react";
import ScheduleTab from "../tabs/ScheduleTab";
import ReportsTab from "../tabs/ReportsTab";
import TrainingTab from "../tabs/TrainingTab";

const WorkerDashboard = () => {
  const [activeTab, setActiveTab] = useState("schedule");
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [selectedReport, setSelectedReport] = useState(null);
  const scrollRef = useRef(null);

  const reportData = {
    'LOC_04': {
      id: 'REP-772',
      title: 'Waste Overflow',
      loc: 'Sector 4',
      citizen: 'A. Smith',
      time: '10:45 AM',
      description: 'The bin at the corner of 5th Ave is completely overflowing. Plastic bottles are everywhere on the sidewalk.',
      img: 'https://images.unsplash.com/photo-1605600611284-19561ad7ddf0?q=80&w=600',
    },
    'LOC_15': {
      id: 'REP-801',
      title: 'Illegal Dumping',
      loc: 'East Gate',
      citizen: 'P. Kumar',
      time: '09:20 AM',
      description: 'Someone left old furniture and construction debris near the park entrance.',
      img: 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?q=80&w=600',
    }
  };

  const handleOpenReport = (locationId) => {
    if (reportData[locationId]) setSelectedReport(reportData[locationId]);
  };

  const tabs = [
    { id: "schedule", label: "Tasks", icon: <Truck size={24} /> },
    { id: "reports", label: "Issues", icon: <AlertCircle size={24} /> },
    { id: "training", label: "Learn", icon: <BookOpen size={24} /> },
  ];

  const scrollToTab = (tabId) => {
    const index = tabs.findIndex(t => t.id === tabId);
    setActiveTab(tabId);
    scrollRef.current.scrollTo({ left: index * window.innerWidth, behavior: "smooth" });
  };

  const handleScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / window.innerWidth);
      if (tabs[index] && tabs[index].id !== activeTab) {
        setActiveTab(tabs[index].id);
      }
    }
  };

  // Reusable Header Component to avoid code duplication in tabs
  const TabHeader = ({ title }) => (
    <div className="w-full flex justify-between items-center mb-10 pt-10 px-2">
      <h2 className="text-3xl font-black italic text-[#47510B] uppercase tracking-tighter">
        {title}<span className="text-[#CAD23C]">.</span>
      </h2>
      <button 
        onClick={() => setIsProfileOpen(true)} 
        className="bg-[#47510B] p-1.5 pr-5 rounded-2xl flex items-center gap-3 border-2 border-white shadow-lg text-[#CAD23C] hover:scale-105 transition-all"
      >
        <div className="w-9 h-9 rounded-xl bg-[#CAD23C] flex items-center justify-center text-[#47510B]">
          <User size={20} strokeWidth={3} />
        </div>
        <span className="font-black text-[11px] uppercase tracking-[0.2em]">Marcus.7729</span>
      </button>
    </div>
  );

  return (
    <div className="h-screen bg-[#FDFAD8] font-sans relative overflow-hidden perspective-1000">

      {/* --- REPORT DETAIL MODAL --- */}
      {selectedReport && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-[#47510B]/95 backdrop-blur-xl">
          <div className="bg-[#FDFAD8] w-full max-w-sm h-[600px] rounded-[50px] border-[8px] border-white overflow-hidden animate-slide-up flex flex-col shadow-2xl">
            <div className="h-44 min-h-[176px] w-full relative shrink-0">
              <img src={selectedReport.img} alt="Evidence" className="w-full h-full object-cover" />
              <button onClick={() => setSelectedReport(null)} className="absolute top-4 right-4 w-10 h-10 bg-white rounded-full flex items-center justify-center text-[#AB1717] shadow-xl"><X size={20} strokeWidth={3} /></button>
            </div>
            <div className="p-8 flex-1 overflow-y-auto no-scrollbar flex flex-col">
              <h4 className="text-2xl font-black text-[#47510B] uppercase italic leading-tight">{selectedReport.title}</h4>
              <div className="flex items-center gap-2 mt-1 mb-6 opacity-40"><MapPin size={12} /><span className="text-[10px] font-black uppercase tracking-widest">{selectedReport.loc}</span></div>
              <div className="p-5 bg-white rounded-3xl border-2 border-[#47510B]/10 italic text-sm text-[#47510B]/80 leading-relaxed shadow-inner mb-6">"{selectedReport.description}"</div>
              <button onClick={() => setSelectedReport(null)} className="mt-auto w-full py-5 bg-[#47510B] text-[#CAD23C] rounded-[25px] font-black uppercase text-sm shadow-xl flex items-center justify-center gap-3"><CheckCircle size={18} /> Mark as Resolved</button>
            </div>
          </div>
        </div>
      )}

      {/* --- PROFILE LAYER --- */}
      <div className={`absolute inset-0 z-[150] transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex items-center justify-center p-4 md:p-12 ${isProfileOpen ? "opacity-100 scale-100" : "opacity-0 scale-125 pointer-events-none"}`}>
        <div className="w-full h-full bg-[#FDFAD8] rounded-[60px] shadow-2xl relative overflow-hidden flex flex-col border-[12px] border-white">
          <button onClick={() => setIsProfileOpen(false)} className="absolute top-6 right-6 w-12 h-12 bg-white rounded-full flex items-center justify-center text-[#47510B] shadow-xl z-50"><X size={24} /></button>
          <div className="flex-1 overflow-y-auto no-scrollbar p-8 md:p-16 text-[#47510B]">
            <h3 className="text-5xl font-black italic uppercase tracking-tighter leading-none mb-12">Marcus<br/><span className="text-[#CAD23C]">Sterling.</span></h3>
            {/* Profile content items... */}
            <div className="p-5 bg-white rounded-[30px] border-2 border-[#47510B]/10 mb-4">
              <p className="text-[9px] font-black text-[#A1AED1] uppercase mb-1 tracking-widest">Registry_Email</p>
              <p className="font-bold text-sm lowercase">m.sterling@trash2track.gov</p>
            </div>
          </div>
        </div>
      </div>

      {/* --- MAIN DASHBOARD LAYER --- */}
      <div className={`h-full w-full transition-all duration-1000 ease-[cubic-bezier(0.23,1,0.32,1)] flex flex-col ${isProfileOpen ? "scale-50 opacity-0 -translate-x-full pointer-events-none" : "scale-100 opacity-100"}`}>

        <main ref={scrollRef} onScroll={handleScroll} className="flex-1 flex overflow-x-auto snap-x snap-mandatory no-scrollbar">

          {/* SCHEDULE SECTION */}
          <section className="min-w-full h-full snap-start px-10 flex flex-col overflow-y-auto no-scrollbar">
            <TabHeader title="Todays Schedule" />
            <ScheduleTab onViewReport={handleOpenReport} />
            <div className="h-32 shrink-0" /> {/* Spacer for footer */}
          </section>

          {/* REPORTS SECTION */}
          <section className="min-w-full h-full snap-start px-10 flex flex-col overflow-y-auto no-scrollbar">
            <TabHeader title="Issues" />
            <ReportsTab onSelectReport={setSelectedReport} />
            <div className="h-32 shrink-0" />
          </section>

          {/* TRAINING SECTION */}
          <section className="min-w-full h-full snap-start px-10 flex flex-col overflow-y-auto no-scrollbar">
            <TabHeader title="Learn" />
            <TrainingTab />
            <div className="h-32 shrink-0" />
          </section>

        </main>

        {/* FOOTER NAV */}
        <footer className="fixed bottom-12 left-1/2 -translate-x-1/2 z-50">
          <nav className="bg-[#47510B]/90 backdrop-blur-3xl border border-white/20 px-4 py-3.5 rounded-[40px] shadow-2xl flex items-center gap-3">
            {tabs.map((tab) => (
              <button 
                key={tab.id} 
                onClick={() => scrollToTab(tab.id)} 
                className={`flex items-center gap-3 px-8 py-4 rounded-[30px] transition-all duration-500 ${activeTab === tab.id ? "bg-[#CAD23C] shadow-xl scale-110" : "text-white/40"}`}
              >
                <div style={{ color: activeTab === tab.id ? '#47510B' : 'inherit' }}>{tab.icon}</div>
                {activeTab === tab.id && <span className="text-[11px] font-[1000] uppercase tracking-widest text-[#47510B]">{tab.label}</span>}
              </button>
            ))}
          </nav>
        </footer>
      </div>
    </div>
  );
};

export default WorkerDashboard;
